const {test}=require('node:test'),assert=require('node:assert/strict'),vm=require('node:vm'),fs=require('node:fs');
const C=require('./collection-flow-model'),P=require('./product-model'),M=require('./model'),L=require('./log-data');
function load(beforeLoad){
 const i={id:'I',version:'wrong',build:'wrong',requests:[],evidence:[],updates:[],status:'调查中'};
 const c={LoganCollection:C,LoganProduct:P,M:{...M},L,state:{sequence:400,issues:[i],collectionRequests:[]},views:{collectioncenter:()=>'',logcenter:()=>''},workUI:{},records:[{time:'10:42:01',level:'INFO',module:'Network',content:'network'},{time:'10:42:05',level:'ERROR',module:'LoginViewModel',content:'loading=true',file:'LoginViewModel.swift',line:124}],JSON,Date,Set,Math,console,TextEncoder,save:()=>true,toast:()=>{},esc:String,btn:()=>'',heading:()=>'',badge:()=>'',openModal:()=>{},render:()=>{},issue:()=>i};
 for(const name of ['product-collection.js','collection-flow.js']){const source=fs.readFileSync(__dirname+'/'+name,'utf8');for(const [,dependency] of source.matchAll(/const (?:product|collection|capture)\w+=(\w+);/g))if(!(dependency in c))c[dependency]=()=>'';for(const [,fn] of source.matchAll(/^(\w+)=function/gm))if(!(fn in c))c[fn]=()=>{};}
 c.fullLogSources=()=>c.state.issues.flatMap(i=>i.requests.map(request=>({issue:i,request,key:i.id+'/'+request.id})));c.collectionSources=()=>c.fullLogSources();c.deskSources=()=>c.fullLogSources().filter(x=>x.request.task);c.$=()=>({classList:{remove(){}}});
 if(beforeLoad)beforeLoad(c,i);
 vm.createContext(c);for(const name of ['product-collection.js','collection-flow.js'])vm.runInContext(fs.readFileSync(__dirname+'/'+name,'utf8'),c);return {c,i};
}
const draft=targetId=>({targetId,begin:'2026-10-19T10:40',end:'2026-10-19T10:45',types:['应用日志','网络日志'],expanded:true,title:'测试'});
test('实际采集适配直到文件返回才记录日志构建，且不拿设备新构建替代',()=>{const {c}=load(),r=C.create(c.state,draft('native-a17'),c.M,P);for(let n=0;n<3;n++)c.M.advance(r);assert.equal(r.build,null);c.M.advance(r);assert.equal(r.build,'38107');assert.equal(r.product.target.latestBuild,'38108');c.M.advance(r);assert.match(r.events.find(e=>e.text.includes('发布')).text,/尚未关联工单/);});
test('独立关联后稳定来源键不变，任务读取实际日志身份',()=>{const {c,i}=load(),r=C.create(c.state,draft('native-a17'),c.M,P);for(let n=0;n<5;n++)c.M.advance(r);const before=c.fullLogSources()[0].key;C.associate(c.state,r.id,i.id);assert.equal(c.fullLogSources()[0].key,before);const task=c.M.tasks(i)[0];assert.equal(task.build,'38107');assert.equal(task.records.length,2);assert.equal(i.build,'wrong');});
test('Web 返回事件来自 Web 文件；部分成功不公开失败类型',()=>{const {c,i}=load(),r=C.create(c.state,{...draft('web-active'),issueId:i.id},c.M,P);r.scenario='partial';for(let n=0;n<5;n++)c.M.advance(r);assert.equal(c.M.tasks(i)[0].platform,'Web');assert.equal(c.M.tasks(i)[0].build,'web-38107');assert.equal(c.M.tasks(i)[0].records.length,4);assert.equal(C.coverage(r).count,4);assert.ok(c.M.tasks(i)[0].records.every(x=>!x.module.includes('Network')));});
test('独立失败重试不借用当前工单元数据，不覆盖父请求',()=>{const {c}=load(),r=C.create(c.state,draft('web-active'),c.M,P);r.scenario='partial';for(let n=0;n<5;n++)c.M.advance(r);c.retryInlineCollection(r.product.stableKey);const retry=c.state.collectionRequests[1];assert.equal(retry.parent,r.id);assert.equal(retry.issueId,null);assert.equal(retry.build,null);assert.equal(retry.product.observed,null);assert.equal(retry.product.stableKey,'collection/'+retry.id);assert.equal(r.status,'部分成功');});
test('独立重解析发布完整新批次，原请求状态不变',()=>{const {c}=load(),r=C.create(c.state,draft('native-a17'),c.M,P);for(let n=0;n<5;n++)c.M.advance(r);c.collectionReparse(r.id);const run=r.product.assets[0].runs[0];assert.equal(run.status,'完成');assert.ok(run.task);assert.equal(run.records.length,2);assert.equal(r.status,'完成');c.collectionReparse(r.id);assert.equal(r.product.assets[0].runs.length,2);});
test('未关联日志不会误进入上次活动工单的阅读与证据上下文',()=>{const {c}=load(),r=C.create(c.state,draft('native-a17'),c.M,P);for(let n=0;n<5;n++)c.M.advance(r);assert.equal(c.fullLogSources().length,1);assert.equal(c.deskSources().length,0);});

test('全部适配加载后恢复新请求选择，不因早期渲染回退旧请求',()=>{let key;const {c}=load((c,i)=>{const r=C.create(c.state,draft('native-a17'),c.M,P);key=r.product.stableKey;c.workUI.collectionKey='I/old';c.initialWorkspaceSelection={active:i.id,workspace:{collectionKey:key},desk:{}};c.desk={issueKeys:{}};c.page='collectioncenter';});assert.equal(c.workUI.collectionKey,key);});
test('新稳定来源键可导出请求记录，独立请求不冒充工单',()=>{const {c}=load(),r=C.create(c.state,draft('native-a17'),c.M,P);let result;c.file=(name,text)=>result=JSON.parse(text);c.exportParseRecord(r.product.stableKey);assert.equal(result.id,r.id);assert.equal(result.issueId,null);assert.equal(result.target.latestBuild,'38108');assert.equal(result.observed,null);});
test('实际推送适配提交后停在通道接受，后续回执才推进到上传与可读',()=>{const {c}=load(),r=C.create(c.state,draft('native-a17'),c.M,P);C.dispatch(r,c.M);assert.equal(r.step,1);assert.equal(r.product.push.status,'通道已接受');assert.equal(r.product.observed,null);assert.equal(r.events.filter(e=>e.text.includes('模拟提交回捞推送')).length,1);c.M.advance(r);assert.equal(r.step,2);assert.equal(r.files.length,0);c.M.advance(r);assert.equal(r.status,'采集中');assert.equal(r.files.length,0);c.M.advance(r);assert.ok(r.files.length);assert.equal(r.task,null);c.M.advance(r);assert.equal(r.status,'完成');});
test('无设备送达回执也可根据 SDK 实际响应继续，不能伪造送达',()=>{const {c}=load(),r=C.create(c.state,draft('native-a17'),c.M,P);r.scenario='noreceipt';C.dispatch(r,c.M);for(let n=0;n<4;n++)c.M.advance(r);assert.equal(r.status,'完成');assert.equal(r.events.some(e=>e.text.includes('回执已收到')),false);assert.ok(r.events.some(e=>e.text.includes('SDK 已确认')));});
test('推送失败后重试有独立推送编号，原回执与失败记录不覆盖',()=>{const {c}=load(),r=C.create(c.state,draft('native-a17'),c.M,P);r.scenario='pushfail';C.dispatch(r,c.M);const old=JSON.stringify(r.product.push);c.retryInlineCollection(r.product.stableKey);const next=c.state.collectionRequests[1];assert.notEqual(next.product.push.id,r.product.push.id);assert.equal(next.product.push.command.requestId,next.id);assert.equal(next.product.push.submittedAt,null);assert.equal(next.product.push.receiptId,null);assert.equal(next.status,'待推送');assert.equal(JSON.stringify(r.product.push),old);C.dispatch(next,c.M);assert.equal(next.product.push.status,'通道已接受');assert.equal(r.status,'推送失败');});
test('取消已提交请求保留接受回执，不能变成从未发送',()=>{const {c}=load(),r=C.create(c.state,draft('native-a17'),c.M,P);C.dispatch(r,c.M);const receipt=r.product.push.receiptId;r.status='已取消';c.M.advance(r);assert.equal(r.product.push.receiptId,receipt);assert.equal(r.product.push.status,'通道已接受');assert.equal(r.status,'已取消');assert.equal(r.files.length,0);});

function loadAli(){const result=load(),c=result.c;c.LoganAliyunRetrieval=require('./aliyun-retrieval-model');c.evidenceMetadata=()=>({build:'wrong',version:'wrong'});c.assetParseView=()=>'';c.findAsset=id=>c.state.issues.flatMap(i=>i.logAssets||[]).find(a=>a.id===id);c.collectForm=()=>{};vm.runInContext(fs.readFileSync(__dirname+'/aliyun-retrieval.js','utf8'),c);return {...result,A:c.LoganAliyunRetrieval};}
test('阿里云回捞适配保留未知身份，收到日志后可独立重新解析',()=>{const {c,A}=loadAli(),r=A.create(c.state,{...A.draft(),targetValue:'qa-device',scenario:'parsefail'},c.M);for(let n=0;n<5;n++)c.M.advance(r);assert.equal(r.product.aliyun.retrievalStatus,'回捞成功');assert.equal(r.build,null);assert.equal(r.product.observed.records[0].sourceVerified,false);c.collectionReparse(r.id);const a=r.product.assets[0];assert.equal(a.build,null);assert.equal(a.runs[0].status,'完成');assert.equal(r.status,'解析失败');assert.equal(r.product.aliyun.retrievalStatus,'回捞成功');});
test('阿里云失败重试保留父请求，生成新的本地关联号',()=>{const {c,A}=loadAli(),r=A.create(c.state,{...A.draft(),targetValue:'qa-device',scenario:'pushfail'},c.M);c.M.advance(r);c.retryInlineCollection(r.product.stableKey);const next=c.state.collectionRequests[1];assert.equal(next.parent,r.id);assert.notEqual(next.product.aliyun.requestId,r.product.aliyun.requestId);assert.equal(r.status,'推送失败');assert.equal(next.status,'通道已接受');});

test('未知日志身份不借用工单版本作为 AI 证据',()=>{const {c,A,i}=loadAli(),r=A.create(c.state,{...A.draft(i),targetValue:'qa-device'},c.M);for(let n=0;n<5;n++)c.M.advance(r);const task=c.M.tasks(i)[0],meta=c.evidenceMetadata(task,task.records[0]);assert.equal(meta.build,null);assert.equal(meta.version,null);assert.equal(meta.versionOrigin,'unknown');assert.equal(meta.sourceVerified,false);});
